"""Utility functions for the random-project."""


def greet(name: str) -> str:
    """Return a greeting message for the given name."""
    return f"Hello, {name}! Welcome to random-project."


def mash_lists(list_a: list, list_b: list) -> list:
    """Interleave two lists into one merged list."""
    result = []
    for a, b in zip(list_a, list_b):
        result.append(a)
        result.append(b)
    result.extend(list_a[len(list_b):])
    result.extend(list_b[len(list_a):])
    return result


def count_colors(colors: list[str]) -> dict[str, int]:
    """Count occurrences of each color in a list."""
    counts: dict[str, int] = {}
    for color in colors:
        counts[color] = counts.get(color, 0) + 1
    return counts


def format_facts(facts: list[str]) -> str:
    """Format a list of facts into a numbered list string."""
    return "\n".join(f"{i+1}. {fact}" for i, fact in enumerate(facts))

